impl Document {
    pub(crate) fn compare_compu(
        &self,
        _other: &Document,
        a: &Compu,
        b: &Compu,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_compu_content() != b.get_compu_content() {
            return Err(format!("{path}: COMPU_CONTENT mismatch"));
        }
        if a.get_compu_default_value() != b.get_compu_default_value() {
            return Err(format!("{path}: COMPU_DEFAULT_VALUE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_const(
        &self,
        _other: &Document,
        a: &CompuConst,
        b: &CompuConst,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_compu_const_content_type() != b.get_compu_const_content_type() {
            return Err(format!("{path}: COMPU_CONST_CONTENT_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_const_content(
        &self,
        _other: &Document,
        a: &CompuConstContent,
        b: &CompuConstContent,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_compu_const_formula_content(
        &self,
        other: &Document,
        a: &CompuConstFormulaContent,
        b: &CompuConstFormulaContent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_compu_const_content(other, a.base(), b.base(), path)?;
        if a.get_vf() != b.get_vf() {
            return Err(format!("{path}: VF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_const_numeric_content(
        &self,
        other: &Document,
        a: &CompuConstNumericContent,
        b: &CompuConstNumericContent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_compu_const_content(other, a.base(), b.base(), path)?;
        if a.get_v() != b.get_v() {
            return Err(format!("{path}: V mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_const_text_content(
        &self,
        other: &Document,
        a: &CompuConstTextContent,
        b: &CompuConstTextContent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_compu_const_content(other, a.base(), b.base(), path)?;
        if a.get_vt() != b.get_vt() {
            return Err(format!("{path}: VT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_content(
        &self,
        _other: &Document,
        a: &CompuContent,
        b: &CompuContent,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_compu_generic_math(
        &self,
        other: &Document,
        a: &CompuGenericMath,
        b: &CompuGenericMath,
        path: &str,
    ) -> Result<(), String> {
        self.compare_formula_expression(other, a.base(), b.base(), path)?;
        if a.get_level() != b.get_level() {
            return Err(format!("{path}: LEVEL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_method(
        &self,
        other: &Document,
        a: &CompuMethod,
        b: &CompuMethod,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_blueprintable(other, a.base(), b.base(), path)?;
        if a.get_compu_internal_to_phys() != b.get_compu_internal_to_phys() {
            return Err(format!("{path}: COMPU_INTERNAL_TO_PHYS mismatch"));
        }
        if a.get_compu_phys_to_internal() != b.get_compu_phys_to_internal() {
            return Err(format!("{path}: COMPU_PHYS_TO_INTERNAL mismatch"));
        }
        if a.get_display_format() != b.get_display_format() {
            return Err(format!("{path}: DISPLAY_FORMAT mismatch"));
        }
        if a.get_unit_ref() != b.get_unit_ref() {
            return Err(format!("{path}: UNIT_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_nominator_denominator(
        &self,
        _other: &Document,
        a: &CompuNominatorDenominator,
        b: &CompuNominatorDenominator,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_v();
        let list_b = b.get_v();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: V length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.V[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_compu_rational_coeffs(
        &self,
        _other: &Document,
        a: &CompuRationalCoeffs,
        b: &CompuRationalCoeffs,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_compu_denominator() != b.get_compu_denominator() {
            return Err(format!("{path}: COMPU_DENOMINATOR mismatch"));
        }
        if a.get_compu_numerator() != b.get_compu_numerator() {
            return Err(format!("{path}: COMPU_NUMERATOR mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_scale(
        &self,
        other: &Document,
        a: &CompuScale,
        b: &CompuScale,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_a2l_display_text() != b.get_a2l_display_text() {
            return Err(format!("{path}: A2L_DISPLAY_TEXT mismatch"));
        }
        if a.get_compu_inverse_value() != b.get_compu_inverse_value() {
            return Err(format!("{path}: COMPU_INVERSE_VALUE mismatch"));
        }
        if a.get_compu_scale_contents() != b.get_compu_scale_contents() {
            return Err(format!("{path}: COMPU_SCALE_CONTENTS mismatch"));
        }
        if a.get_desc() != b.get_desc() {
            return Err(format!("{path}: DESC mismatch"));
        }
        if a.get_lower_limit() != b.get_lower_limit() {
            return Err(format!("{path}: LOWER_LIMIT mismatch"));
        }
        if a.get_mask() != b.get_mask() {
            return Err(format!("{path}: MASK mismatch"));
        }
        if a.get_short_label() != b.get_short_label() {
            return Err(format!("{path}: SHORT_LABEL mismatch"));
        }
        if a.get_symbol() != b.get_symbol() {
            return Err(format!("{path}: SYMBOL mismatch"));
        }
        if a.get_upper_limit() != b.get_upper_limit() {
            return Err(format!("{path}: UPPER_LIMIT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_scale_constant_contents(
        &self,
        other: &Document,
        a: &CompuScaleConstantContents,
        b: &CompuScaleConstantContents,
        path: &str,
    ) -> Result<(), String> {
        self.compare_compu_scale_contents(other, a.base(), b.base(), path)?;
        if a.get_compu_const() != b.get_compu_const() {
            return Err(format!("{path}: COMPU_CONST mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_scale_contents(
        &self,
        _other: &Document,
        a: &CompuScaleContents,
        b: &CompuScaleContents,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_compu_scale_rational_formula(
        &self,
        other: &Document,
        a: &CompuScaleRationalFormula,
        b: &CompuScaleRationalFormula,
        path: &str,
    ) -> Result<(), String> {
        self.compare_compu_scale_contents(other, a.base(), b.base(), path)?;
        if a.get_compu_rational_coeffs() != b.get_compu_rational_coeffs() {
            return Err(format!("{path}: COMPU_RATIONAL_COEFFS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_compu_scales(
        &self,
        other: &Document,
        a: &CompuScales,
        b: &CompuScales,
        path: &str,
    ) -> Result<(), String> {
        self.compare_compu_content(other, a.base(), b.base(), path)?;
        let list_a = a.get_compu_scales();
        let list_b = b.get_compu_scales();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: COMPU_SCALES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.compu_scales.get(*x).ok_or_else(|| {
                format!("{path}.COMPU_SCALES[{index}]: id not found in own arena")
            })?;
            let y = other.compu_scales.get(*y).ok_or_else(|| {
                format!("{path}.COMPU_SCALES[{index}]: id not found in other arena")
            })?;
            self.compare_compu_scale(other, x, y, &format!("{path}.COMPU_SCALES[{index}]"))?;
        }
        Ok(())
    }
}
